import{_ as l,a0 as t,w as d,s as c,ao as o,I as i,x as e,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"用復古電腦程序 Toy CPU 學習低級編程 | LCTT x X-CMD","titleTemplate":false,"description":"用復古電腦程序 Toy CPU 學習低級編程 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用復古電腦程序 Toy CPU 學習低級編程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用復古電腦程序 Toy CPU 學習低級編程 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20230104.0 ⭐️⭐️ Learn to code with my retro computer program","title":"用復古電腦程序 Toy CPU 學習低級編程","tag":"202301","desc":""},"relativePath":"202301/20230104.0 ⭐️⭐️ Learn to code with my retro computer program.md","filePath":"[post].md"}'),r={name:"202301/20230104.0 ⭐️⭐️ Learn to code with my retro computer program.md"};function h(u,s,g,k,b,T){const a=t("Link");return d(),c("div",null,[s[22]||(s[22]=o('<h1 id="用復古電腦程序-toy-cpu-學習低級編程" tabindex="-1">用復古電腦程序 Toy CPU 學習低級編程 <a class="header-anchor" href="#用復古電腦程序-toy-cpu-學習低級編程" aria-label="Permalink to “用復古電腦程序 Toy CPU 學習低級編程”">​</a></h1><p><img src="https://opensource.com/sites/default/files/lead-images/retro_old_unix_computer.png" alt=""></p><blockquote><p>我寫了一個名為 “Toy CPU” 的教育性復古計算機程序，以便我的學生能夠學習機器語言。</p></blockquote><p>我兼職教授大學課程，包括一個對所有專業開放的一般計算機主題的課程。這是一門入門課程，向學生講授技術是如何運作的，以消除圍繞計算的神秘感。</p><p>雖然不是計算機科學課程，但這門課的一個部分涉及計算機編程。我通常用非常抽象的術語談論編程，所以不會讓聽眾聽不懂。但是今年，我想讓我的學生以 “老派” 的方式做一些需要 “動手” 的編程。同時，我又想保持簡單，以便讓每個人都能跟上。</p><p>我喜歡將我的課程結構化，以顯示你是如何從 “那裏” 到 “這裏” 的。理想情況下，我會讓我的學生學習如何編寫一個簡單的程序。然後，我將從這裏開始，展示現代編程是如何讓開發人員創建更復雜的程序的。我決定嘗試一種非常規的方法 —— 教學生學習終極的低級別編程語言：機器語言。</p><h3 id="機器語言編程" tabindex="-1">機器語言編程 <a class="header-anchor" href="#機器語言編程" aria-label="Permalink to “機器語言編程”">​</a></h3><p>早期的個人電腦如 Apple II（1977 年）、TRS-80（1977 年）和 IBM PC（1981 年）讓用户用鍵盤輸入程序，並在屏幕上顯示結果。但計算機並不總是帶有屏幕和鍵盤。</p><p>Altair 8800 和 IMSAI 8080（均為 1975 年製造）要求用户使用面板上的 “開關和燈” 輸入程序。你可以用機器語言輸入指令，使用一組開關，機器會點亮 LED 燈以代表每個二進制指令的 1 和 0。</p><p><img src="https://opensource.com/sites/default/files/2022-12/MITS_Altair_8800_Computer_%281975%29.png" alt="Altair 8800 計算機的圖片"></p><p>對這些早期機器進行編程，需要了解被稱為 “<ruby>操作碼<rt>opcode</rt></ruby>” （操作代碼的簡稱）的機器語言指令，以執行基本操作，如將兩個數字相加或將一個值存儲到計算機的存儲器中。我想向我的學生展示程序員是如何通過開關和燈，手工輸入一系列指令和內存地址的。</p><p>然而，在這門課上，使用實際的 Altair 8800 就有點太複雜了。我需要一些簡單的、任何初級水平的學生都能掌握的東西。理想情況下，我希望能找到一個簡單的 “業餘” 復古計算機，其工作原理與 Altair 8800 相似，但我無法找到一個價格低於 100 美元的合適的 “類似 Altair” 的設備。我找到了幾個 “Altair” 軟件模擬器，但它們忠實地再現了 Altair 8800 的操作碼，這對我的需求來説太過沉重。</p>',12)),i("p",null,[s[3]||(s[3]=e("我決定編寫我自己的 “教育” 復古計算機。我稱它為 “Toy CPU”。你可以在我的 ",-1)),n(a,{href:"https://github.com/freedosproject/toycpu"},{default:p(()=>[...s[0]||(s[0]=[e("GitHub 代碼庫",-1)])]),_:1}),s[4]||(s[4]=e(" 上找到它，包括幾個可以運行的版本。第一版是一個實驗性的原型，運行在 ",-1)),n(a,{href:"https://opensource.com/downloads/guide-using-freedos"},{default:p(()=>[...s[1]||(s[1]=[e("FreeDOS",-1)])]),_:1}),s[5]||(s[5]=e(" 上。第二版是一個更新的原型，在 Linux 上用 ",-1)),n(a,{href:"https://opensource.com/article/21/8/ncurses-linux"},{default:p(()=>[...s[2]||(s[2]=[e("ncurses",-1)])]),_:1}),s[6]||(s[6]=e(" 運行。版本 3 是一個 FreeDOS 程序，在圖形模式下運行。",-1))]),s[23]||(s[23]=o(`<h3 id="toy-cpu-的編程" tabindex="-1">Toy CPU 的編程 <a class="header-anchor" href="#toy-cpu-的編程" aria-label="Permalink to “Toy CPU 的編程”">​</a></h3><p>Toy CPU 是一個非常簡單的復古計算機。它只有 256 字節的內存和一個最小化的指令集，其目的是在複製 “開關和燈” 編程模式的同時保持簡單化。它的界面模仿 Altair 8800，有一系列 8 個 LED 燈，分別代表計數器（程序的 “行號”）、指令、累積器（用於臨時數據的內部存儲器）和狀態。</p><p>當你啓動 Toy CPU 時，它通過清除內存來模擬 “啓動”。當它啓動時，它也會在屏幕右下方的狀態燈中顯示 “INI”（初始化）。“PWR”（電源）燈亮表示 Toy CPU 已被打開。</p><p><img src="https://opensource.com/sites/default/files/2022-12/toycpu.png" alt="Toy CPU 的啓動屏幕"></p><p>當 Toy CPU 準備好讓你進入一個程序時，它通過狀態燈指示 “INP”（“輸入”模式），並讓你從程序的計數器 0 開始。Toy CPU 的程序總是從計數器 0 開始。</p><p>在 “輸入” 模式下，用上下方向鍵顯示不同的程序計數器，按回車鍵編輯當前計數器上的指令。當你進入 “編輯” 模式時，Toy CPU 的狀態燈上會顯示 “EDT”（“編輯” 模式）。</p><p><img src="https://opensource.com/sites/default/files/2022-12/edit0-load.png" alt="Toy CPU 編輯屏幕"></p><p>Toy CPU 有一張速查表，被 “貼” 在顯示屏的前面。它列出了 Toy CPU 可以處理的不同操作碼。</p><ul><li><code>00000000</code>（<code>STOP</code>）：停止程序執行。</li><li><code>00000001</code>（<code>RIGHT</code>）：將累加器中的位向右移動一個位置。值 <code>00000010</code> 變成 <code>00000001</code>，<code>00000001</code> 變成 <code>00000000</code>。</li><li><code>00000010</code>（<code>LEFT</code>）：將累加器中的位向左移動一個位置。值 <code>01000000</code> 變成 <code>10000000</code>，<code>10000000</code> 變成 <code>00000000</code>。</li><li><code>00001111</code>（<code>NOT</code>）：對累加器進行二進制非操作。例如，值 <code>10001000</code> 變成 <code>01110111</code>。</li><li><code>00010001</code>（<code>AND</code>）：對累加器用存儲在某一地址的值進行二進制與操作。該地址被存儲在下一個計數器中。</li><li><code>00010010</code>（<code>OR</code>）：對累積器用存儲在某一地址的值進行二進制或運算。</li><li><code>00010011</code>（<code>XOR</code>）：對累加器用存儲在某一地址的值進行二進制異或運算。</li><li><code>00010100</code>（<code>LOAD</code>）：將一個地址的值加載（複製）到累加器中。</li><li><code>00010101</code>（<code>STORE</code>）： 存儲（複製）累加器中的值到一個地址。</li><li><code>00010110</code>（<code>ADD</code>）：將存儲在某一地址的數值加入到累加器中。</li><li><code>00010111</code>（<code>SUB</code>）：從累積器中減去儲存在某一地址的數值。</li><li><code>00011000</code>（<code>GOTO</code>）：轉到（跳到）一個計數器地址。</li><li><code>00011001</code>（<code>IFZERO</code>）：如果累加器為零，轉到（跳到）一個計數器地址。</li><li><code>10000000</code>（<code>NOP</code>）：空操作，可以安全地忽略。</li></ul><p>當處於 “編輯” 模式時，使用左右方向鍵選擇操作碼中的一個位，然後按空格鍵在關閉（0）和開啓（1）之間翻轉數值。當你完成編輯後，按回車鍵回到 “輸入” 模式。</p><p><img src="https://opensource.com/sites/default/files/2022-12/input0-load.png" alt="Toy CPU 輸入模式屏幕"></p><h3 id="一個示例程序" tabindex="-1">一個示例程序 <a class="header-anchor" href="#一個示例程序" aria-label="Permalink to “一個示例程序”">​</a></h3><p>我想通過輸入一個簡短的程序來探索 Toy CPU，將兩個數值相加，並將結果存儲在 Toy CPU 的內存中。實際上，這執行的是算術運算 <code>A+B=C</code>。要創建這個程序，你只需要幾個操作碼：</p><ul><li><code>00010100</code>（<code>LOAD</code>）</li><li><code>00010110</code>（<code>ADD</code>）</li><li><code>00010101</code>（<code>STORE</code>）</li><li><code>00000000</code>（<code>STOP</code>）</li></ul><p><code>LOAD</code>、<code>ADD</code> 和 <code>STORE</code> 指令需要一個內存地址，這個地址總是在下一個計數器的位置。例如，程序的前兩條指令是:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>計數器 0：00010100</span></span>
<span class="line"><span>計數器 1：某個內存地址，第一個值 A 存放在那裏</span></span></code></pre></div><p>計數器 0 中的指令是 <code>LOAD</code> 操作，計數器 1 中的值是你存儲某個值的內存地址。這兩條指令一起將內存中的數值複製到 Toy CPU 的累加器中，在那裏你可以對該數值進行操作。</p><p>將一個數字 <code>A</code> 裝入累加器後，你需要將數值 <code>B</code> 加到它上面。你可以用這兩條指令來做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>計數器 2：00010110</span></span>
<span class="line"><span>計數器 3：存儲第二個值 B 的內存地址</span></span></code></pre></div><p>假設你把值 <code>1</code>（<code>A</code>）裝入累加器，然後把值 <code>3</code>（<code>B</code>）加到它上面。現在累加器的值是 <code>4</code>。現在你需要用這兩條指令把數值 <code>4</code> 複製到另一個內存地址（<code>C</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>計數器 4：00010101</span></span>
<span class="line"><span>計數器 5：一個內存地址（C），我們可以在那裏保存新的值</span></span></code></pre></div><p>把這兩個值加在一起後，現在可以用這條指令結束程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>計數器 6: 00000000</span></span></code></pre></div><p>計數器 6 之後的任何指令都可以供程序作為存儲內存使用。這意味着你可以用計數器 7 的內存來儲存值 <code>A</code>，計數器 8 的內存來儲存值 <code>B</code> ，計數器 9 的內存來儲存值 <code>C</code>。你需要將這些分別輸入到 Toy CPU 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>計數器 7：00000001（1）</span></span>
<span class="line"><span>計數器 8：00000011（3）</span></span>
<span class="line"><span>計數器 9：00000000（0，以後會被覆蓋）</span></span></code></pre></div><p>在弄清了所有指令和 <code>A</code>、<code>B</code> 和 <code>C</code> 的內存位置後，現在可以將完整的程序輸入到 Toy CPU 中。這個程序將數值 1 和 3 相加，得到 4：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>計數器 0：00010100</span></span>
<span class="line"><span>計數器 1：00000111（7）</span></span>
<span class="line"><span>計數器 2：00010110</span></span>
<span class="line"><span>計數器 3：00001000（8）</span></span>
<span class="line"><span>計數器 4：00010101</span></span>
<span class="line"><span>計數器 5：00001001（9）</span></span>
<span class="line"><span>計數器 6：00000000</span></span>
<span class="line"><span>計數器 7：00000001（1）</span></span>
<span class="line"><span>計數器 8：00000011（3）</span></span>
<span class="line"><span>計數器 9：00000000（0，以後會被覆蓋）</span></span></code></pre></div><p>要運行程序，在 “輸入” 模式下按下 <code>R</code> 鍵。Toy CPU 將在狀態燈中顯示 “RUN”（“運行” 模式），並從計數器 0 開始執行你的程序。</p><p>Toy CPU 有一個明顯的延遲，所以你可以看到它執行程序中的每一步。隨着程序的進行，你應該看到計數器從 <code>00000000</code>（0）移動到 <code>00000110</code>（6）。在計數器 1 之後，程序從內存位置 7 加載數值 <code>1</code>，累積器更新為 <code>00000001</code>（1）。在計數器 3 之後，程序將加數值 <code>3</code>，並更新累加器顯示 <code>00000100</code>（4）。累加器將保持這種狀態，直到程序在計數器 5 之後將數值存入內存位置 9，然後在計數器 6 結束。</p><p><img src="https://opensource.com/sites/default/files/2022-12/run-3.png" alt="在運行模式下的 Toy CPU"></p><h3 id="探索機器語言編程" tabindex="-1">探索機器語言編程 <a class="header-anchor" href="#探索機器語言編程" aria-label="Permalink to “探索機器語言編程”">​</a></h3><p>你可以使用 Toy CPU 來創建其他程序，並進一步探索機器語言編程。通過用機器語言編寫這些程序來測試你的創造力。</p><h3 id="一個在累積器上閃燈的程序" tabindex="-1">一個在累積器上閃燈的程序 <a class="header-anchor" href="#一個在累積器上閃燈的程序" aria-label="Permalink to “一個在累積器上閃燈的程序”">​</a></h3><p>你能點亮累加器上的右四位，然後是左四位，然後是所有的位嗎？你可以用兩種方法之一來寫這個程序。</p><p>一種直接的方法是，從不同的內存地址加載三個數值，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>計數器 0：LOAD</span></span>
<span class="line"><span>計數器 1：“右邊”</span></span>
<span class="line"><span>計數器 2：LOAD</span></span>
<span class="line"><span>計數器 3：“左邊”</span></span>
<span class="line"><span>計數器 4：LOAD</span></span>
<span class="line"><span>計數器 5：“所有”</span></span>
<span class="line"><span>計數器 6：STOP</span></span>
<span class="line"><span>計數器 7：00001111（“右邊”）</span></span>
<span class="line"><span>計數器 8：11110000（“左邊”）</span></span>
<span class="line"><span>計數器 9：11111111（“全部”）</span></span></code></pre></div><p>寫這個程序的另一種方法是嘗試使用 <code>NOT</code> 和 <code>OR</code> 二進制操作。這樣可以得到一個更小的程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>計數器 0：LOAD</span></span>
<span class="line"><span>計數器 1：“右邊”</span></span>
<span class="line"><span>計數器 2：NOT</span></span>
<span class="line"><span>計數器 3：OR</span></span>
<span class="line"><span>計數器 4：“右邊”</span></span>
<span class="line"><span>計數器 5：STOP</span></span>
<span class="line"><span>計數器 6：00001111（“右邊”）</span></span></code></pre></div><h3 id="從一個數字開始倒數" tabindex="-1">從一個數字開始倒數 <a class="header-anchor" href="#從一個數字開始倒數" aria-label="Permalink to “從一個數字開始倒數”">​</a></h3><p>你可以把 Toy CPU 作為一個倒數計時器。這個程序行使 <code>IFZERO</code> 測試，只有當累加器為零時，程序才會跳轉到一個新的計數器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>計數器 0：LOAD</span></span>
<span class="line"><span>計數器 1：“初始值”</span></span>
<span class="line"><span>計數器 2：IFZERO（這也是倒計時的“開始”）</span></span>
<span class="line"><span>計數器 3：“結束”</span></span>
<span class="line"><span>計數器 4：SUB</span></span>
<span class="line"><span>計數器 5：“1”</span></span>
<span class="line"><span>計數器 6：GOTO</span></span>
<span class="line"><span>計數器 7：“開始”</span></span>
<span class="line"><span>計數器 8：STOP</span></span>
<span class="line"><span>計數器 9：00000111（“初始值”）</span></span>
<span class="line"><span>計數器 10：00000001（“1”）</span></span></code></pre></div><p>Toy CPU 是學習機器語言的一個好方法。我在入門課程中使用了 Toy CPU，學生們説他們發現寫第一個程序很困難，但寫下一個程序就容易多了。學生們還表示，用這種方式編寫程序其實很有趣，他們學到了很多關於計算機實際工作的知識。Toy CPU 既具有教育性，也很有趣味性！</p><hr>`,43)),i("p",null,[s[8]||(s[8]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/23/1/learn-machine-language-retro-computer"},{default:p(()=>[...s[7]||(s[7]=[e("https://opensource.com/article/23/1/learn-machine-language-retro-computer",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/jim-hall"},{default:p(()=>[...s[9]||(s[9]=[e("Jim Hall",-1)])]),_:1}),s[14]||(s[14]=e(" 選題：",-1)),n(a,{href:"https://github.com/lkxed"},{default:p(()=>[...s[10]||(s[10]=[e("lkxed",-1)])]),_:1}),s[15]||(s[15]=e(" 譯者：",-1)),n(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[11]||(s[11]=[e("wxy",-1)])]),_:1}),s[16]||(s[16]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[19]||(s[19]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[17]||(s[17]=[e("LCTT",-1)])]),_:1}),s[20]||(s[20]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:p(()=>[...s[18]||(s[18]=[e("Linux中國",-1)])]),_:1}),s[21]||(s[21]=e(" 榮譽推出",-1))])])}const m=l(r,[["render",h]]);export{f as __pageData,m as default};
